import 'package:flutter_bloc/flutter_bloc.dart';import '../../../../Core/Resources/app_colors.dart';import '../../../../Core/Resources/app_icons.dart';import '../../../../Core/Utils/Extensions/localizations_extension.dart';import 'package:convex_bottom_bar/convex_bottom_bar.dart';import 'package:flutter/material.dart';import '../manager/main_cubit.dart';class BuildBottomNavigationBar extends StatelessWidget {  const BuildBottomNavigationBar({    super.key,  });  @override  Widget build(BuildContext context) {    return ConvexAppBar(      initialActiveIndex: 0,      elevation: 5,      // height: 55.h,      color: AppColors.grayscale70,      activeColor: AppColors.primaryColor,      backgroundColor: AppColors.white,      style: TabStyle.fixedCircle,      items: [        TabItem(          icon: AppIcons.homeOutline,          activeIcon: AppIcons.homeFill,          title: context.appStrings.Home,        ),        TabItem(          icon: AppIcons.compassOutline,          activeIcon: AppIcons.compassFill,          title: context.appStrings.Explore,        ),        TabItem(          icon: AppIcons.scan,          title: context.appStrings.Scan,        ),        TabItem(          icon: AppIcons.heartsOutline,          activeIcon: AppIcons.heartFill,          title: context.appStrings.Favourite,        ),        TabItem(          icon: AppIcons.profileOutline,          activeIcon: AppIcons.profileFill,          title: context.appStrings.Profile,        ),      ],      onTap: (int i) => context.read<MainCubit>().changeIndex(i),    );  }}